    "La oferta pública inicial ( IPO o también OPI) de Anthropic marca una prueba decisiva para el modelo financiero que ha impulsado su expansión: varios de sus principales inversores también le venden la infraestructura necesaria para entrenar y operar sus sistemas de inteligencia artificial."
